import React, { useEffect, useState } from "react";
import {
  Box, Typography, Table, TableHead, TableRow,
  TableCell, TableBody, Paper, TableContainer,
  Button, Dialog, DialogTitle, DialogContent,
  TextField, DialogActions, Chip
} from "@mui/material";

import {
  fetchDrivers,
  addDriver,
  deleteDriver,
  updateDriverStatus
} from "./api";

export default function Drivers() {
  const [drivers, setDrivers] = useState([]);
  const [openAdd, setOpenAdd] = useState(false);
  const [form, setForm] = useState({
    name: "",
    phone: "",
    vehicle: "",
    city: ""
  });

  const load = async () => {
    const data = await fetchDrivers();
    setDrivers(data);
  };

  useEffect(() => {
    load();
  }, []);

  const handleAdd = async () => {
    await addDriver(form);
    setOpenAdd(false);
    setForm({ name: "", phone: "", vehicle: "", city: "" });
    load();
  };

  const toggleStatus = async (id, current) => {
    const newStatus = current === "Available" ? "Busy" : "Available";
    await updateDriverStatus(id, newStatus);
    load();
  };

  const remove = async (id) => {
    if (window.confirm("Delete this driver?")) {
      await deleteDriver(id);
      load();
    }
  };

  return (
    <Box sx={{ padding: 3 }}>
      <Typography variant="h5" gutterBottom>
        Driver Management
      </Typography>

      <Button variant="contained" onClick={() => setOpenAdd(true)}>
        Add Driver
      </Button>

      <TableContainer component={Paper} sx={{ mt: 3 }}>
        <Table>
          <TableHead sx={{ background: "#eee" }}>
            <TableRow>
              <TableCell>ID</TableCell>
              <TableCell>Name</TableCell>
              <TableCell>Phone</TableCell>
              <TableCell>Vehicle</TableCell>
              <TableCell>City</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Actions</TableCell>
            </TableRow>
          </TableHead>

          <TableBody>
            {drivers.map((d) => (
              <TableRow key={d.id}>
                <TableCell>{d.id}</TableCell>
                <TableCell>{d.name}</TableCell>
                <TableCell>{d.phone}</TableCell>
                <TableCell>{d.vehicle}</TableCell>
                <TableCell>{d.city}</TableCell>

                <TableCell>
                  <Chip
                    label={d.status}
                    color={d.status === "Available" ? "success" : "warning"}
                    onClick={() => toggleStatus(d.id, d.status)}
                    sx={{ cursor: "pointer" }}
                  />
                </TableCell>

                <TableCell>
                  <Button
                    variant="contained"
                    color="error"
                    onClick={() => remove(d.id)}
                  >
                    Delete
                  </Button>
                </TableCell>
              </TableRow>
            ))}

            {drivers.length === 0 && (
              <TableRow>
                <TableCell colSpan={7} align="center">
                  No drivers added yet.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={openAdd} onClose={() => setOpenAdd(false)}>
        <DialogTitle>Add Driver</DialogTitle>

        <DialogContent>
          <TextField
            label="Name"
            fullWidth
            sx={{ mt: 1 }}
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
          />

          <TextField
            label="Phone"
            fullWidth
            sx={{ mt: 1 }}
            value={form.phone}
            onChange={(e) => setForm({ ...form, phone: e.target.value })}
          />

          <TextField
            label="Vehicle"
            fullWidth
            sx={{ mt: 1 }}
            value={form.vehicle}
            onChange={(e) => setForm({ ...form, vehicle: e.target.value })}
          />

          <TextField
            label="City"
            fullWidth
            sx={{ mt: 1 }}
            value={form.city}
            onChange={(e) => setForm({ ...form, city: e.target.value })}
          />
        </DialogContent>

        <DialogActions>
          <Button onClick={() => setOpenAdd(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleAdd}>
            Add
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}
